test('requestCompleted receives null instead of undefined on a successful request', async t => {
  t.plan(2)

  let resolveCompleted
  const completed = new Promise(resolve => { resolveCompleted = resolve })

  const fastify = Fastify({
    logController: new class extends LogController {
      requestCompleted (error, request, reply, metadata) {
        resolveCompleted(error)
      }
    }()
  })
  t.after(() => fastify.close())

  fastify.get('/', (req, reply) => {
    reply.send({ hello: 'world' })
  })

  const res = await fastify.inject('/')
  t.assert.strictEqual(res.statusCode, 200)
  t.assert.strictEqual(await completed, null)
})

